from collections.abc import Mapping
from datetime import date


def prepare_expedition(data, divisions, leaders):
    if not isinstance(data, Mapping):
        raise ValueError("data must be a mapping")

    required = {"name", "brief", "division", "leader", "start"}
    optional = {"finish", "accepting_members", "sponsored", "tags"}
    if not required.issubset(data):
        raise ValueError("missing required field")
    if set(data) - required - optional:
        raise ValueError("unknown field")

    text = {}
    for key in ("name", "brief", "division", "leader"):
        value = data[key]
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f"{key} must be a nonempty string")
        text[key] = value.strip()

    if text["division"] not in divisions:
        raise ValueError("unknown division")
    if text["leader"] not in leaders:
        raise ValueError("unknown leader")

    start = data["start"]
    finish = data.get("finish")
    if not isinstance(start, date):
        raise ValueError("start must be a date")
    if finish is not None and not isinstance(finish, date):
        raise ValueError("finish must be a date or None")
    if finish is not None and finish < start:
        raise ValueError("finish precedes start")

    accepting = data.get("accepting_members", False)
    sponsored = data.get("sponsored", False)
    if type(accepting) is not bool or type(sponsored) is not bool:
        raise ValueError("flags must be booleans")

    tags = data.get("tags", [])
    if not isinstance(tags, list):
        raise ValueError("tags must be a list")
    if any(not isinstance(tag, str) or not tag for tag in tags):
        raise ValueError("tags must contain nonempty strings")

    return {
        "name": text["name"],
        "brief": text["brief"],
        "division": text["division"],
        "leader": text["leader"],
        "start": start,
        "finish": finish,
        "accepting_members": accepting,
        "sponsored": sponsored,
        "tags": tags,
    }

